"""subtitle_generator: Convert transcription blocks to SRT/VTT text.

Each block dict must have: text (str), start_ms (int), end_ms (int).
Also provides split_blocks_on_tags which resolves <split:N> markers into
separate sub-blocks for finer-grained subtitle segmentation.
"""
from __future__ import annotations

import re
from typing import Any


# ── Timestamp helpers ─────────────────────────────────────────────────────────

def _ms_to_parts(ms: int) -> tuple[int, int, int, int]:
    ms = max(0, int(ms))
    h = ms // 3_600_000; ms %= 3_600_000
    m = ms // 60_000;    ms %= 60_000
    s = ms // 1_000;     ms %= 1_000
    return h, m, s, ms


def format_timestamp_srt(ms: int) -> str:
    """Return SRT timestamp: HH:MM:SS,mmm"""
    h, m, s, mil = _ms_to_parts(ms)
    return f"{h:02d}:{m:02d}:{s:02d},{mil:03d}"


def format_timestamp_vtt(ms: int) -> str:
    """Return WebVTT timestamp: HH:MM:SS.mmm"""
    return format_timestamp_srt(ms).replace(",", ".")


# ── Split-tag resolver ────────────────────────────────────────────────────────

def split_blocks_on_tags(blocks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Resolve <split:N> tags inside block text into separate sub-blocks.

    Each <split:N> tag marks a boundary where N is the absolute timestamp in ms
    at which the new sub-block starts. The previous block ends at N.

    Blocks without <split:N> tags are returned unchanged.
    """
    result: list[dict[str, Any]] = []
    tag_pattern = re.compile(r"<split:(\d+)>")

    for block in blocks:
        text = block.get("text", "")
        parts = tag_pattern.split(text)

        if len(parts) == 1:
            # No split tags — pass through unchanged
            result.append(block)
            continue

        # parts alternates: text, timestamp_str, text, timestamp_str, ..., text
        current_start = block.get("start_ms", 0)
        block_end = block.get("end_ms", 0)

        # Build list of (text_segment, end_ms) pairs
        segments: list[tuple[str, int]] = []
        i = 0
        while i < len(parts) - 1:
            seg_text = parts[i].strip()
            split_ms = int(parts[i + 1])
            segments.append((seg_text, split_ms))
            i += 2
        # Last text chunk ends at block's own end_ms
        last_text = parts[-1].strip()
        segments.append((last_text, block_end))

        for seg_text, seg_end in segments:
            if seg_text:
                result.append({
                    **{k: v for k, v in block.items() if k not in ("text", "start_ms", "end_ms")},
                    "text": seg_text,
                    "start_ms": current_start,
                    "end_ms": seg_end,
                })
            current_start = seg_end

    return result


# ── Generators ────────────────────────────────────────────────────────────────

def generate_srt(blocks: list[dict[str, Any]]) -> str:
    """Generate a valid SRT string from a list of transcription blocks.

    Zero-duration blocks (start_ms == end_ms) are silently skipped.
    """
    lines: list[str] = []
    index = 1
    for block in blocks:
        start = int(block.get("start_ms") or 0)
        end = int(block.get("end_ms") or 0)
        text = (block.get("text") or "").strip()

        if not text or start == end:
            continue

        lines.append(
            f"{index}\n"
            f"{format_timestamp_srt(start)} --> {format_timestamp_srt(end)}\n"
            f"{text}"
        )
        index += 1

    return "\n\n".join(lines)


def generate_vtt(blocks: list[dict[str, Any]]) -> str:
    """Generate a valid WebVTT string from a list of transcription blocks."""
    cues: list[str] = []
    index = 1
    for block in blocks:
        start = int(block.get("start_ms") or 0)
        end = int(block.get("end_ms") or 0)
        text = (block.get("text") or "").strip()

        if not text or start == end:
            continue

        cues.append(
            f"{index}\n"
            f"{format_timestamp_vtt(start)} --> {format_timestamp_vtt(end)}\n"
            f"{text}"
        )
        index += 1

    return "WEBVTT\n\n" + "\n\n".join(cues)
